var scene = UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/City.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var roots = scene.GetRootGameObjects();
Sim.Jobs.JobCompletionResultPanel panel = null;
foreach (var r in roots) {
    panel = r.GetComponentInChildren<Sim.Jobs.JobCompletionResultPanel>(true);
    if (panel != null) break;
}
if (panel == null) { Debug.LogError("panel null"); return; }

var card = panel.transform.Find("Modal/Card");
var timeView = card.Find("Time View");
if (timeView == null) { Debug.LogError("Time View not found"); return; }

// Duplicate Time View as the basis for MiniGame View (same layout: Rating + Duration)
var mgGO = UnityEngine.Object.Instantiate(timeView.gameObject, card);
mgGO.name = "MiniGame View";

// Remove the duplicated TimeResultView component and add MiniGameResultView
var oldTimeView = mgGO.GetComponent<Sim.Jobs.TimeResultView>();
if (oldTimeView != null) UnityEngine.Object.DestroyImmediate(oldTimeView, true);

var mgView = mgGO.AddComponent<Sim.Jobs.MiniGameResultView>();
var rating = mgGO.transform.Find("Rating");
var duration = mgGO.transform.Find("Duration");
var soMG = new UnityEditor.SerializedObject(mgView);
soMG.Update();
soMG.FindProperty("ratingLabel").objectReferenceValue = rating != null ? rating.GetComponent<TMPro.TMP_Text>() : null;
soMG.FindProperty("durationLabel").objectReferenceValue = duration != null ? duration.GetComponent<TMPro.TMP_Text>() : null;
soMG.ApplyModifiedProperties();

// Make sure MG view sits before Close button
var close = card.Find("Close");
if (close != null) close.SetAsLastSibling();

// Append to panel.views array
var soPanel = new UnityEditor.SerializedObject(panel);
soPanel.Update();
var viewsProp = soPanel.FindProperty("views");
int idx = viewsProp.arraySize;
viewsProp.InsertArrayElementAtIndex(idx);
viewsProp.GetArrayElementAtIndex(idx).objectReferenceValue = mgView;
soPanel.ApplyModifiedProperties();

UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
Debug.Log("[MG] MiniGame View added iid=" + mgView.GetInstanceID() + " — scene saved.");
